begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(17);
insert into auth.users(id,email,role,aud,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) values('99000000-0000-4000-8000-000000000001','sync-owner@example.test','authenticated','authenticated',now(),'{}','{}');
insert into auth.sessions(id,user_id,created_at,updated_at,aal)values('99000000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000001',now(),now(),'aal2');
insert into private.account_policy_acceptances select '99000000-0000-4000-8000-000000000001',terms_version,privacy_version,now(),'review' from private.account_policy_versions where id on conflict do nothing;
insert into public.organizations(id,name,slug)values('99000000-0000-4000-8000-000000000003','Sync test','sync-test');
insert into public.organization_memberships(organization_id,user_id,role,status,joined_at)values('99000000-0000-4000-8000-000000000003','99000000-0000-4000-8000-000000000001','owner','active',now());
insert into public.productions(id,organization_id,name,slug)values('99000000-0000-4000-8000-000000000004','99000000-0000-4000-8000-000000000003','Sync test','sync-test');
insert into public.schedules(id,organization_id,production_id,display_name,slug,document,created_by,updated_by)values('99000000-0000-4000-8000-000000000005','99000000-0000-4000-8000-000000000003','99000000-0000-4000-8000-000000000004','Sync test','sync-test','{"meta":{},"rows":[]}','99000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001');
insert into private.trial_sync_integrations(id,organization_id,netlify_site_id,legacy_origin,enabled,authorized_by,authorized_at)values('99000000-0000-4000-8000-000000000006','99000000-0000-4000-8000-000000000003','99000000-0000-4000-8000-000000000007','https://fictional.netlify.app',true,'99000000-0000-4000-8000-000000000001',now());
insert into private.trial_sync_mappings(id,integration_id,schedule_id,legacy_key,state)values('99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000006','99000000-0000-4000-8000-000000000005','Sync test','{"status":"content-conflict","observed":{"netlify":{"version":"a"},"supabase":{"version":"1"}}}');
select ok(not has_function_privilege('anon','public.read_trial_sync_review(uuid)','EXECUTE'),'anonymous cannot review');
select ok(not has_function_privilege('service_role','public.begin_trial_sync_resolution(uuid,uuid,bigint,text)','EXECUTE'),'machine cannot authorize human choice');
select ok(not has_function_privilege('authenticated','public.claim_scoped_trial_sync_mapping(uuid,uuid,uuid[])','EXECUTE'),'user cannot claim automated work');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub','99000000-0000-4000-8000-000000000001','session_id','99000000-0000-4000-8000-000000000002','exp',extract(epoch from now()+interval '1 hour')::bigint,'aal','aal1')::text,true);
set local role authenticated;
select throws_ok($q$select public.read_trial_sync_review('99000000-0000-4000-8000-000000000008')$q$,'PT403','mfa_required','Owner review needs MFA');
select set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||jsonb_build_object('aal','aal2','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',extract(epoch from now())::bigint))))::text,true);
select is(public.read_trial_sync_review('99000000-0000-4000-8000-000000000008')->>'sequence','0','Owner can read comparison');
select throws_ok($q$select public.read_trial_sync_review('99000000-0000-4000-8000-000000000099')$q$,'PT404','Sync unavailable','unknown mapping denied');
select throws_ok($q$select public.begin_trial_sync_resolution('99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000009',1,'netlify')$q$,'PT409','Comparison changed or in progress','stale review denied');
select is(public.begin_trial_sync_resolution('99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000009',0,'netlify')->>'state','claimed','exact review receives exclusive lease');
select throws_ok($q$select public.begin_trial_sync_resolution('99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000010',0,'supabase')$q$,'PT409','Comparison changed or in progress','overlapping choice denied');
reset role;
select is((select count(*) from public.audit_events where action='trial_sync.resolution_requested' and resource_id='99000000-0000-4000-8000-000000000005'),1::bigint,'human choice audited once');
set local role service_role;
select throws_ok($q$select public.claim_scoped_trial_sync_mapping('99000000-0000-4000-8000-000000000006','99000000-0000-4000-8000-000000000010','{}')$q$,'PT400','Explicit mapping scope required','empty pilot cannot expand');
select throws_ok($q$select public.claim_scoped_trial_sync_mapping('99000000-0000-4000-8000-000000000006','99000000-0000-4000-8000-000000000010',array['99000000-0000-4000-8000-000000000099']::uuid[])$q$,'PT409','Mapping scope changed','foreign mapping denied');
select is(public.claim_scoped_trial_sync_mapping('99000000-0000-4000-8000-000000000006','99000000-0000-4000-8000-000000000010',array['99000000-0000-4000-8000-000000000008']::uuid[])->>'state','idle','worker cannot take human lease');
reset role;
update private.trial_sync_mappings set lease_until=now()-interval '1 second',checked_at=now()-interval '1 minute' where id='99000000-0000-4000-8000-000000000008';
set local role service_role;
select is(public.claim_scoped_trial_sync_mapping('99000000-0000-4000-8000-000000000006','99000000-0000-4000-8000-000000000010',array['99000000-0000-4000-8000-000000000008']::uuid[])->>'state','claimed','expired lease can recover within scope');
reset role;
update private.trial_sync_integrations set enabled=false where id='99000000-0000-4000-8000-000000000006';
set local role authenticated;
select throws_ok($q$select public.begin_trial_sync_resolution('99000000-0000-4000-8000-000000000008','99000000-0000-4000-8000-000000000009',0,'netlify')$q$,'PT403','Sync disabled','paused writes denied');
select is(public.read_trial_sync_review('99000000-0000-4000-8000-000000000008')->>'enabled','false','paused review still readable');
reset role;
delete from auth.sessions where id='99000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($q$select public.read_trial_sync_review('99000000-0000-4000-8000-000000000008')$q$,'PT401','Active session required','revoked session denied');
reset role;
select * from finish();
rollback;
